contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint256 amount, uint256 prevAllowance) public {
        // set up an arbitrary previous allowance
        c.approve(spender, prevAllowance);
        uint256 before = c.allowance(address(this), spender);
        // the deciding call: a fresh approve must overwrite, not add
        c.approve(spender, amount);
        uint256 afterAllowance = c.allowance(address(this), spender);
        assert(afterAllowance == amount && (before == prevAllowance));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 shareAmount) public payable {
        // Fresh pool: this contract holds no shares, but read the real balance.
        uint256 myShares = c.balanceOf(address(this));

        bool reverted;
        try c.sellShares(shareAmount, address(this), 0, 0, "", type(uint256).max) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: sellShares reverts exactly when shareAmount exceeds
        // the caller's share balance (other failure conditions are excluded
        // by zero minimums and a far-future deadline).
        if (shareAmount > myShares) {
            assert(reverted);
        } else {
            assert(!reverted);
        }
    }

    receive() external payable {}
}

