contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint256 approveAmt, uint256 amount) public payable {
        require(approveAmt >= amount);
        // fund this contract with shares by minting via buyShares (totalSupply == 0 path)
        require(amount > 3004, "need shares");
        c.approve(spender, approveAmt);
        uint256 allowBefore = c.allowance(address(this), spender);
        // make a first transferFrom for (amount - 2000) to reach a nonzero transferable balance state
        c.transferFrom(address(this), spender, amount - 2000);
        uint256 allowMid = c.allowance(address(this), spender);
        uint256 balSpenderBefore = c.balanceOf(spender);
        bool ok = c.transferFrom(address(this), spender, 2000);
        uint256 allowAfter = c.allowance(address(this), spender);
        uint256 balSpenderAfter = c.balanceOf(spender);
        assert(ok && allowBefore == approveAmt && allowMid == approveAmt - (amount - 2000) && allowAfter == allowMid - 2000 && balSpenderAfter == balSpenderBefore + 2000);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 amount, uint256 seedAmount) public payable {
        require(to != address(this));
        // seed the caller's balance by approving and transferring from an allowance holder path:
        // simplest: mint-free seeding via approve + transferFrom is not possible; instead use c.transfer
        // after acquiring shares via buyShares is not feasible without tokens.
        // Instead seed balance directly: the test contract may already hold shares? Fallback: use
        // approve-based flow only if it has shares. We assert the rule conditional on success.
        // Give the caller shares by transferring from the zero-balance case would revert, so:
        // ensure a successful transfer by first self-funding is impossible; thus we test the
        // revert-free path only when balance suffices.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();
        require(balBefore >= amount);
        require(seedAmount >= 0); // no-op guard
        bool ok = c.transfer(to, amount);
        uint256 balAfter = c.balanceOf(address(this));
        uint256 toAfter = c.balanceOf(to);
        uint256 supplyAfter = c.totalSupply();
        assert(ok && balBefore - amount == balAfter && toBefore + amount == toAfter && supplyBefore == supplyAfter);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) public payable {
        require(deadline >= block.timestamp);

        bytes32 domainSeparator = c.DOMAIN_SEPARATOR();
        bytes32 PERMIT_TYPEHASH = c.PERMIT_TYPEHASH();
        uint256 nonceBefore = c.nonces(owner);

        bytes32 digest = keccak256(
            abi.encodePacked(
                "\x19\x01",
                domainSeparator,
                keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonceBefore, deadline))
            )
        );

        address recovered = ecrecover(digest, v, r, s);
        require(recovered != owner);

        bool reverted;
        try c.permit(owner, spender, value, deadline, v, r, s) { reverted = false; } catch { reverted = true; }

        assert(reverted && c.allowance(owner, spender) == 0 && c.nonces(owner) == nonceBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address owner, address spender, uint256 amount, uint256 allowanceAmt) public {
        require(amount > allowanceAmt);
        require(allowanceAmt < type(uint256).max);

        // set up: owner holds shares and approves this contract (msg.sender on c) some allowance
        c.transfer(owner, 0);
        uint256 ownerBalBefore = c.balanceOf(owner);
        uint256 spenderBalBefore = c.balanceOf(spender);

        // cannot set allowance for arbitrary owner directly; instead approve from this contract's own balance
        // use owner = address(this) via transfer to self? Instead: approve then transferFrom own shares.
        // Simpler: this contract approves itself for allowanceAmt tokens and attempts transferFrom more.
        bool ok = c.approve(address(this), allowanceAmt);
        require(ok);
        uint256 selfBalBefore = c.balanceOf(address(this));
        require(selfBalBefore < amount || allowanceAmt < amount);

        bool reverted;
        try c.transferFrom(address(this), spender, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted &&
            c.balanceOf(address(this)) == selfBalBefore &&
            c.balanceOf(spender) == spenderBalBefore &&
            c.balanceOf(owner) == ownerBalBefore &&
            c.allowance(address(this), address(this)) == allowanceAmt
        );
    }
    receive() external payable {}
}
